def check_ramsey():
    # We can use z3 to check if there is a graph on 14 vertices with no K5 and no I3
    from z3 import Bool, Solver, Or, Not, And, sat
    import itertools

    s = Solver()
    edges = {}
    for i in range(14):
        for j in range(i+1, 14):
            edges[(i, j)] = Bool(f"e_{i}_{j}")

    # No K5
    for comb in itertools.combinations(range(14), 5):
        s.add(Not(And([edges[(i, j)] for i, j in itertools.combinations(comb, 2)])))

    # No I3
    for comb in itertools.combinations(range(14), 3):
        s.add(Not(And([Not(edges[(i, j)]) for i, j in itertools.combinations(comb, 2)])))

    res = s.check()
    print(res)

check_ramsey()

